#!/usr/bin/env python3
"""Build Zawatu's portable static website using only the Python standard library."""
import html
import json
import os
import re
import shutil
from pathlib import Path
from urllib.parse import quote

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'dist/fr'
SITE = json.loads((ROOT / 'content/site.json').read_text())
ARTICLES = json.loads((ROOT / 'content/articles_fr.json').read_text())
BASE = os.environ.get('SITE_BASE_PATH', '').rstrip('/') + '/fr'
if BASE and (not BASE.startswith('/') or '..' in BASE or '?' in BASE or '#' in BASE):
    raise ValueError('SITE_BASE_PATH must be an absolute URL path prefix')
ORIGIN = os.environ.get('SITE_URL', SITE['url']).rstrip('/')
if not ORIGIN.startswith(('https://','http://')):
    raise ValueError('SITE_URL must be an HTTP(S) origin')
def esc(s): return html.escape(str(s), quote=True)
def url(path=''): return BASE + '/' + path.lstrip('/')
def link(path, text, cls=''): return f'<a class="{cls}" href="{url(path)}">{text}</a>'

SERVICES = [
    dict(slug='marque-contenu', number='01', name='Marque & contenu', short='Une promesse claire. Des contenus qui lui donnent vie.', body='Nous clarifions votre message et le traduisons en contenus cohérents : portraits, photographie, vidéos courtes, textes et supports de présentation.', deliver=['Atelier de positionnement et messages clés','Calendrier éditorial adapté à vos publics','Production photo, vidéo et textes selon le périmètre','Déclinaisons pour les canaux retenus'], goal='Pour une entreprise qui veut expliquer son offre et entretenir une présence régulière.', measure='Livrables validés, régularité, réactions utiles et demandes reçues.', poster='UNE MARQUE.<br>UNE VOIX.<br><em>UNE DIRECTION.</em>'),
    dict(slug='campagnes-activations', number='02', name='Campagnes & activations', short='Une idée qui donne une raison d’agir.', body='Lancement, démonstration, cadeau utile ou journée découverte : nous construisons une opération autour de votre public, de votre offre et de vos moyens.', deliver=['Concept, mécanique de participation et budget détaillé','Coordination des partenaires et fournisseurs retenus','Contenus de campagne et supports terrain','Suivi des livraisons et bilan de l’opération'], goal='Pour une marque qui prépare une occasion précise : lancement, saison commerciale ou rencontre clients.', measure='Participation, cadeaux distribués, demandes, visites ou ventes documentées selon le dispositif.', poster='UNE IDÉE.<br>UN MOMENT.<br><em>UNE ACTION.</em>'),
    dict(slug='relations-publiques', number='03', name='Relations publiques', short='Faire comprendre votre histoire aux bonnes personnes.', body='Nous structurons votre présentation, vos messages et votre prise de parole, puis préparons une approche ciblée des médias et interlocuteurs pertinents.', deliver=['Messages clés et dossier de présentation','Préparation d’interview et de prise de parole','Liste de contacts pertinente et cycle de prise de contact','Coordination des échanges et suivi des retours'], goal='Pour une organisation qui annonce une initiative, présente un dirigeant ou prépare une prise de parole.', measure='Documents livrés, contacts qualifiés, réponses et publications effectivement obtenues. La couverture éditoriale reste à la décision des médias.', poster='UNE HISTOIRE.<br>DU CONTEXTE.<br><em>DE LA CLARTÉ.</em>'),
    dict(slug='partenariats-commerciaux', number='04', name='Partenariats commerciaux', short='Des besoins précis. Des rencontres pertinentes.', body='Nous aidons à définir le partenaire recherché, examiner des candidats et organiser les échanges entre entreprises, acheteurs, fournisseurs ou sponsors.', deliver=['Brief de recherche et critères de sélection','Identification et examen de partenaires possibles','Préparation des présentations et rendez-vous','Suivi des échanges et propositions reçues'], goal='Pour un acheteur qui cherche un fournisseur, ou un fournisseur qui veut rencontrer des clients pertinents.', measure='Pertinence des contacts, réunions tenues, devis et accords documentés. Le mandat précise les intérêts représentés et les commissions éventuelles.', poster='LE BON BESOIN.<br>LE BON CONTACT.<br><em>LA RENCONTRE.</em>')
]

def header(active=''):
    items=[('agence/','L’agence','agence'),('services/','Expertises','services'),('campagnes/','Concepts','campagnes'),('journal/','Le blog','journal')]
    nav=''.join(f'<a href="{url(p)}" {"aria-current=page" if k==active else ""}>{t}</a>' for p,t,k in items)
    return f'''<a class="skip" href="#contenu">Aller au contenu</a><header><a href="{url()}" class="wordmark" aria-label="Zawatu accueil"><img class="brand-logo" src="{url("assets/logo.svg")}" alt="Zawatu" width="200" height="45"></a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav">Menu <span>＋</span></button><nav id="main-nav" aria-label="Navigation principale">{nav}<a href="{os.environ.get('SITE_BASE_PATH','').rstrip('/')+'/consulting/technical/'}">Conseil technique (EN)</a>{link('contact/','Contact','nav-cta')}<a href="{os.environ.get('SITE_BASE_PATH','').rstrip('/')+'/'}">EN</a></nav></header>'''

def footer():
    socials=''.join(f'<a href="{esc(v)}" rel="noopener noreferrer">{esc(k)} ↗</a>' for k,v in SITE.get('socials',{}).items() if v.startswith('https://'))
    if SITE.get('whatsapp'): socials+='<a href="https://wa.me/'+''.join(c for c in SITE['whatsapp'] if c.isdigit())+'">WhatsApp ↗</a>'
    return f'''<footer><div class="footer-top"><div><a href="{url()}" class="wordmark"><img class="brand-logo" src="{url("assets/logo.svg")}" alt="Zawatu" width="200" height="45"></a><p>Des histoires qui ouvrent des portes.</p></div><div><span class="eyebrow">EXPLORER</span>{link('agence/','L’agence')}{link('services/','Nos expertises')}{link('journal/','Le blog')}</div><div><span class="eyebrow">COLLABORER</span>{link('campagnes/','Concepts de campagne')}{link('partenariats/','Médias & partenaires')}{link('contact/','Préparer un projet')}</div><div><span class="eyebrow">NOTRE BUREAU</span><p>Bancobu Ikirezi<br>Nouveau bâtiment, 5e étage<br>Burundi</p><p>Médias · Marketing<br>Relations publiques<br>Partenariats commerciaux</p>{socials}</div></div><div class="footer-bottom"><span>© 2026 Zawatu</span>{link('transparence/','Transparence & confidentialité')}<span>Clarté. Créativité. Connexions.</span></div></footer>'''

def write(path,title,desc,body,active='',article=None):
    canonical=ORIGIN+url(path)
    schema={'@context':'https://schema.org','@type':'Article' if article else 'WebPage','name':title,'url':canonical,'inLanguage':'fr'}
    if article: schema.update(headline=article['title'],datePublished=article['date'],author={'@type':'Organization','name':article['author']})
    markup=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#18251e"><title>{esc(title)} — Zawatu</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{esc(canonical)}"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{esc(canonical)}"><meta property="og:locale" content="fr_BI"><link rel="icon" href="{url('assets/favicon.svg')}" type="image/svg+xml"><link rel="alternate" type="application/rss+xml" title="Journal Zawatu" href="{url('feed.xml')}"><link rel="stylesheet" href="{url('assets/site.css')}"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False).replace('<','&lt;')}</script><script src="{url('assets/site.js')}" defer></script></head><body>{header(active)}<main id="contenu">{body}</main>{footer()}</body></html>'''
    dest=OUT/path/'index.html' if path else OUT/'index.html'
    dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(markup)
    PAGES.append(path)

def pagehero(label,title,desc): return f'<section class="page-hero wrap"><p class="eyebrow">{label}</p><h1>{title}</h1><p class="lede">{desc}</p></section>'
def cta(): return f'<section class="contact-band wrap"><span class="eyebrow">VOTRE PROCHAINE ÉTAPE</span><h2>Une idée à faire connaître ?<br><em>Commençons par votre objectif.</em></h2>{link("contact/","Préparer mon projet ↗","solid")}</section>'
def servicecards(): return '<div class="service-list">'+''.join(f'<a href="{url("services/"+s["slug"]+"/")}" class="service-row"><span class="serif">{s["number"]}</span><h3>{s["name"]}</h3><p>{s["short"]}</p><span class="arrow">↗</span></a>' for s in SERVICES)+'</div>'
def articlecard(a,i):
    labels=['LE MESSAGE<br>AVANT LE<br><em>MÉGAPHONE.</em>','LE BON CADEAU.<br>LA BONNE<br><em>OFFRE.</em>','UNE TABLE.<br>LES BONNES<br><em>PERSONNES.</em>','UNE HISTOIRE.<br>DES FAITS.<br><em>DU SENS.</em>','UN FOURNISSEUR.<br>DES CRITÈRES.<br><em>UN CHOIX.</em>','DE L’ATTENTION.<br>ET ENSUITE ?<br><em>MESURER.</em>']
    return f'<article class="article-card" data-category="{esc(a["category"])}" data-search="{esc(a["title"]+" "+a["category"])}"><a href="{url("journal/"+a["slug"]+"/")}"><div class="article-art art-{i%3}"><span>{labels[i%len(labels)]}</span><small>Z / JOURNAL</small></div><p class="article-meta">{esc(a["category"])} · GUIDE PRATIQUE</p><h3>{esc(a["title"])}</h3><span class="read">Lire l’article ↗</span></a></article>'

if OUT.exists(): shutil.rmtree(OUT)
(OUT/'assets').mkdir(parents=True)
shutil.copy(ROOT/'assets/legacy.css',OUT/'assets/site.css')
for name in ['site.js','favicon.svg','logo.svg','logo-white.svg','symbol.svg','symbol-white.svg']: shutil.copy(ROOT/'assets'/name,OUT/'assets'/name)
(OUT/'.nojekyll').touch()
PAGES=[]

hero=f'''<section class="hero wrap"><div class="eyebrow"><span class="dot"></span> MÉDIAS & PARTENARIATS · COLLABORATIONS INTERNATIONALES</div><div class="hero-grid"><div><h1>Des histoires<br>qui ouvrent<br><em>des portes.</em></h1><p class="hero-description">Faire découvrir une marque. Donner envie d’essayer. Réunir les bons partenaires.</p><div class="hero-actions">{link('services/','Découvrir nos expertises ↗','solid')}{link('journal/','Explorer le journal','text-link')}</div></div><div class="hero-poster" aria-label="Une idée, les bonnes personnes, une occasion d’agir"><span>ZAWATU / L’ESPRIT</span><div class="poster-orbit"><span>↗</span></div><h2>Une idée.<br>Les bonnes personnes.<br><em>Une occasion d’agir.</em></h2><small>CRÉER DES LIENS. FAIRE AVANCER LES IDÉES.</small></div></div></section><div class="ticker" aria-hidden="true">HISTOIRES &nbsp; ↗ &nbsp; MARQUES &nbsp; ↗ &nbsp; RENCONTRES &nbsp; ↗ &nbsp; OPPORTUNITÉS &nbsp; ↗ &nbsp; HISTOIRES</div>'''
home=hero+f'''<section class="section wrap"><div class="section-top"><span class="eyebrow">01 / NOS EXPERTISES</span><span>Une idée, jusqu’à son exécution.</span></div><div class="intro-grid"><h2>De la visibilité<br><em>à la rencontre.</em></h2><p>Nous construisons des campagnes qui relient une histoire, un public et une prochaine étape concrète. Notre travail associe création de contenu, relations publiques et coordination commerciale.</p></div>{servicecards()}</section><section class="campaign section wrap"><div class="section-top"><span class="eyebrow">02 / LE LABORATOIRE D’IDÉES</span><span>Concept illustratif · à construire ensemble</span></div><div class="campaign-grid"><div class="umbrella-poster"><span>ZAWATU / CONCEPT 001</span><div class="umbrella">☂</div><strong>Une attention<br>qui reste.</strong><small>LE CADEAU UTILE, AU CŒUR DE LA CAMPAGNE.</small></div><div><h2>Un objet utile.<br><em>Une marque qui accompagne.</em></h2><p>Un commerçant, un fournisseur et une offre client : réunir les éléments d’une campagne de cadeaux personnalisés, de l’échantillon à la communication.</p>{link('campagnes/','Explorer les concepts ↗','text-link')}</div></div></section><section class="section wrap"><div class="section-top"><span class="eyebrow">03 / LE BLOG</span>{link('journal/','Tous les articles ↗')}</div><h2>À découvrir.<br><em>À comprendre. À essayer.</em></h2><div class="articles">{''.join(articlecard(a,i) for i,a in enumerate(ARTICLES[:3]))}</div></section><section class="method section wrap"><span class="eyebrow">04 / NOTRE MÉTHODE</span><h2>Une campagne se prépare.<br><em>Un résultat se documente.</em></h2><div class="steps"><article><b>01 / ÉCOUTER</b><p>Votre objectif, votre public et vos contraintes.</p></article><article><b>02 / CONSTRUIRE</b><p>Une offre, une histoire et les bons partenaires.</p></article><article><b>03 / ACTIVER</b><p>Des contenus et des actions, en ligne et sur le terrain.</p></article><article><b>04 / APPRENDRE</b><p>Un bilan des livrables et des résultats observables.</p></article></div></section>'''+cta()
write('', 'Des histoires qui ouvrent des portes','Zawatu : agence de médias, marketing, relations publiques et partenariats commerciaux depuis le Burundi, avec une ambition internationale.',home)

write('services/','Nos expertises','Marque, contenu, campagnes, relations publiques et partenariats commerciaux : découvrez les expertises Zawatu.',pagehero('LES EXPERTISES','Quatre façons<br><em>d’ouvrir des portes.</em>','Un besoin précis, une proposition adaptée et un périmètre clair. Découvrez comment nous pouvons structurer votre prochain projet.')+f'<section class="section wrap">{servicecards()}</section><section class="section wrap"><span class="eyebrow">COMMENT COLLABORER</span><h2>Le bon format<br><em>pour votre besoin.</em></h2><div class="three-grid"><article><span class="number">01</span><h3>Une présence régulière</h3><p>Un accompagnement mensuel avec calendrier, contenus et bilan. Les canaux et volumes sont convenus ensemble.</p></article><article><span class="number">02</span><h3>Un projet délimité</h3><p>Un lancement, une démonstration ou une campagne avec un objectif, des dates et un budget identifiés.</p></article><article><span class="number">03</span><h3>Un mandat de recherche</h3><p>Des critères pour chercher un fournisseur, un sponsor ou un partenaire, puis préparer les échanges.</p></article></div><p class="fine">Chaque mission fait l’objet d’une proposition. Les frais de production, publicité, déplacements ou tiers sont précisés séparément.</p></section>'+cta(),'services')

for s in SERVICES:
    body=pagehero('EXPERTISE / '+s['number'],s['name'].replace(' & ',' &<br><em>')+('</em>' if ' & ' in s['name'] else ''),s['short'])
    body+=f'<section class="section wrap"><div class="campaign-grid"><div class="type-poster tone-{int(s["number"])%3}">{s["poster"]}<small>ZAWATU / {s["number"]}</small></div><div><h2>Le point de départ.</h2><p class="lede">{s["body"]}</p><p>{s["goal"]}</p></div></div></section><section class="section wrap"><div class="intro-grid"><div><span class="eyebrow">LE PÉRIMÈTRE</span><h2>Ce que nous<br><em>pouvons préparer.</em></h2></div><ul class="deliverables">'+''.join(f'<li>{x}</li>' for x in s['deliver'])+f'</ul></div></section><section class="section wrap soft"><span class="eyebrow">LE SUIVI</span><h2>Observer, puis améliorer.</h2><p class="measure">{s["measure"]}</p><p class="fine">Le périmètre final, les délais, les responsabilités et les indicateurs sont convenus avant le démarrage.</p></section>'+cta()
    write('services/'+s['slug']+'/',s['name'],s['short'],body,'services')

about=pagehero('L’AGENCE','Nous croyons<br><em>aux bonnes connexions.</em>','Zawatu développe une approche qui réunit médias, créativité et partenariats commerciaux depuis le Burundi, avec une ambition internationale.')+'''<section class="section wrap"><div class="intro-grid"><h2>Une histoire mérite<br><em>une direction.</em></h2><div><p>Une entreprise peut avoir un bon produit et manquer d’un message clair, d’une occasion de le présenter ou du bon interlocuteur. Notre rôle est de travailler sur ces liens, au-delà des frontières.</p><p>Nous partons du besoin : comprendre le public, préciser l’offre, choisir les supports et réunir les personnes nécessaires. Les moyens suivent l’objectif.</p></div></div></section><section class="section wrap soft"><span class="eyebrow">NOTRE POSITIONNEMENT</span><div class="three-grid"><article><h3>Créativité utile</h3><p>Une idée doit aider le public à comprendre, découvrir ou agir.</p></article><article><h3>Clarté commerciale</h3><p>Des livrables, responsabilités et dépenses définis avant l’exécution.</p></article><article><h3>Confiance durable</h3><p>Des affirmations étayées, des partenariats identifiables et des résultats présentés avec leurs limites.</p></article></div></section><section class="section wrap"><span class="eyebrow">L’ESPRIT ZAWATU</span><h2>Faire connaître.<br>Donner du contexte.<br><em>Créer l’occasion.</em></h2><p class="measure">Notre journal propose des guides et des découvertes. Notre agence accompagne des projets. Les collaborations rémunérées sont identifiées pour que le lecteur sache ce qu’il consulte.</p></section>'''+cta()
write('agence/','L’agence','Découvrez l’approche Zawatu : créativité utile, clarté commerciale et bonnes connexions depuis le Burundi, avec une ambition internationale.',about,'agence')

concepts=[('01','Une attention qui reste.','Le cadeau utile','Une boutique offre un objet personnalisé aux clients qui remplissent des conditions d’achat clairement annoncées.','Un commerce · un fournisseur · un public client','Échantillon approuvé, stock disponible, conditions de remise et budget complet.','☂'),('02','Une marque, en vrai.','La journée découverte','Plusieurs marques complémentaires se présentent dans un lieu commun, avec démonstrations et points de vente identifiés.','Des marques · un lieu · des visiteurs','Participation confirmée, capacité d’accueil, démonstrations et suivi des demandes.','↗'),('03','Autour de la bonne table.','La rencontre acheteurs-fournisseurs','Une série de rendez-vous est organisée autour de besoins d’achat recueillis avant l’événement.','Des acheteurs · des fournisseurs · un organisateur','Critères de sélection, rendez-vous convenus et responsabilités commerciales explicites.','↔')]
campaigns=pagehero('LE LABORATOIRE D’IDÉES','Créer l’occasion.<br><em>Puis réunir les moyens.</em>','Ces concepts illustrent notre manière de relier les intérêts d’une marque, d’un partenaire et d’un public. Ce ne sont pas des campagnes clients déjà réalisées.')
for n,t,st,desc,people,checks,symbol in concepts:
    campaigns+=f'<section class="section wrap"><div class="campaign-grid"><div class="concept-poster tone-{int(n)%3}"><span>CONCEPT / {n}</span><div class="concept-symbol">{symbol}</div><strong>{t}</strong></div><div><span class="eyebrow">{st.upper()}</span><h2>{t}</h2><p>{desc}</p><p><b>Les participants</b><br>{people}</p><p><b>À préparer</b><br>{checks}</p>{link("contact/","Préparer un concept similaire ↗","text-link")}</div></div></section>'
